-- READ ONLY. Fresh trusted SQL Editor session on VERIFIED rekansiaga-staging.
-- After approved COMMIT, BEFORE adding fixtures. Never execute inside deployment.
-- Local preparation only; not PostgreSQL-runtime-validated by Codex.
-- Hard baseline assertions + complete existing structure manifest + seed queries.
-- A count/assertion success is NOT authenticated API acceptance or staging READY.
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SELECT CURRENT_TIMESTAMP AS captured_at,current_user AS executing_role,
 current_database() AS database_name,
 'Operator must separately record Dashboard staging project reference' AS target_identity_note;
DO $persisted_baseline_checks$
DECLARE
 v_tables text[];
 v_expected text[] := ARRAY['api_idempotency_keys','app_settings','articles','audit_logs','data_sources','disaster_events','donation_campaigns','emergency_contacts','event_locations','event_updates','mitigation_checklist_items','mitigation_guides','notification_deliveries','notification_rules','notification_subscriptions','notifications','public_reports','regions','relief_locations','report_access_tokens','report_attachments','report_status_history','roles','source_sync_logs','staff_profiles','staff_role_assignments'];
 v_signature text;
BEGIN
 SELECT array_agg(c.relname::text ORDER BY c.relname::text COLLATE pg_catalog."C") INTO v_tables
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='public' AND c.relkind IN ('r','p');
 IF v_tables IS DISTINCT FROM v_expected OR EXISTS (
   SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
   WHERE n.nspname='public' AND c.relkind IN ('r','p')
    AND (NOT c.relrowsecurity OR pg_get_userbyid(c.relowner)<>'postgres')) THEN
  RAISE EXCEPTION 'Expected exact 26 postgres-owned tables with RLS enabled';
 END IF;
 IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
     WHERE n.nspname='public') <> 6 THEN
  RAISE EXCEPTION 'Expected exactly six public routines';
 END IF;
 FOREACH v_signature IN ARRAY ARRAY['public.rls_auto_enable()','public.set_updated_at()','public.has_staff_role(text[])','public.review_public_report(uuid,text,text)','public.submit_public_report(text,text,text,uuid,text,double precision,double precision)','public.track_public_report(text,text)'] LOOP
  IF to_regprocedure(v_signature) IS NULL OR NOT EXISTS (
    SELECT 1 FROM pg_proc WHERE oid=to_regprocedure(v_signature)
     AND prokind='f' AND pg_get_userbyid(proowner)='postgres') THEN
   RAISE EXCEPTION 'Expected postgres-owned function missing: %',v_signature;
  END IF;
 END LOOP;
 -- 106 = PK26 + FK33 + UNIQUE13 + CHECK34; NOT NULL is checked as column metadata.
 -- PostgreSQL 18 also records NOT NULL constraints in pg_constraint.
 IF (SELECT count(*) FROM pg_constraint WHERE contype IN ('p','f','u','c') AND conrelid IN
     (SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname='public' AND c.relkind IN ('r','p'))) <> 106 OR EXISTS (
     SELECT 1 FROM pg_constraint WHERE connamespace='public'::regnamespace AND NOT convalidated) THEN
  RAISE EXCEPTION 'PK/FK/UNIQUE/CHECK count or constraint validation mismatch';
 END IF;
 IF (SELECT count(*) FROM pg_indexes WHERE schemaname='public') <> 61 OR EXISTS (
     SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid
     WHERE c.relnamespace='public'::regnamespace AND (NOT i.indisvalid OR NOT i.indisready)) THEN
  RAISE EXCEPTION 'Index count/validity mismatch';
 END IF;
 IF (SELECT count(*) FROM pg_policies WHERE schemaname='public') <> 26 OR
    (SELECT count(*) FROM pg_trigger g JOIN pg_class c ON c.oid=g.tgrelid
     WHERE c.relnamespace='public'::regnamespace AND NOT g.tgisinternal) <> 6 THEN
  RAISE EXCEPTION 'Policy/row trigger count mismatch; use full structural validation';
 END IF;
 IF (SELECT count(*) FROM public.roles) <> 4 OR EXISTS (
   SELECT * FROM (VALUES
    ('super_admin','Super Administrator','System management'),
    ('information_manager','Information Manager','Disaster data and articles'),
    ('report_verifier','Report Verifier','Review community reports'),
    ('mitigation_editor','Mitigation Editor','Maintain disaster guidance')) e(code,name,description)
   WHERE NOT EXISTS (SELECT 1 FROM public.roles r WHERE r.code=e.code
    AND r.name=e.name AND r.description=e.description)) THEN
  RAISE EXCEPTION 'Four exact baseline role seeds required';
 END IF;
 IF (SELECT count(*) FROM public.data_sources) <> 2 OR
    NOT EXISTS (SELECT 1 FROM public.data_sources WHERE name='BMKG'
      AND source_type='official_api' AND official_url='https://data.bmkg.go.id'
      AND is_active AND api_identifier IS NULL) OR
    NOT EXISTS (SELECT 1 FROM public.data_sources WHERE name='RekanSiaga Admin'
      AND source_type='manual' AND official_url IS NULL AND is_active AND api_identifier IS NULL) THEN
  RAISE EXCEPTION 'Two exact baseline data source configurations required';
 END IF;
 IF EXISTS (SELECT 1 FROM public.staff_profiles) OR
    EXISTS (SELECT 1 FROM public.staff_role_assignments) OR
    EXISTS (SELECT 1 FROM public.public_reports) OR
    EXISTS (SELECT 1 FROM public.report_status_history) OR
    EXISTS (SELECT 1 FROM public.report_access_tokens) THEN
  RAISE EXCEPTION 'No accounts, assignments or report fixtures allowed in bootstrap';
 END IF;
 IF md5(pg_get_functiondef('public.rls_auto_enable()'::regprocedure)) IS DISTINCT FROM
     '846ec2fbff751d24b890656d63c3a9bf' OR NOT EXISTS (
   SELECT 1 FROM pg_event_trigger WHERE evtname='ensure_rls'
    AND evtfoid='public.rls_auto_enable()'::regprocedure AND evtenabled='O'
    AND evtevent='ddl_command_end' AND pg_get_userbyid(evtowner)='postgres'
    AND evttags=ARRAY['CREATE TABLE','CREATE TABLE AS','SELECT INTO']::text[]) THEN
  RAISE EXCEPTION 'Reviewed existing helper/event drifted';
 END IF;
END;
$persisted_baseline_checks$;

-- Full expected column/default/constraint/index/policy/grant/function manifest:
