expected_tables AS (SELECT jsonb_array_elements_text(data->'tables') AS name FROM expected),
actual_tables AS (SELECT c.*,n.nspname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='public' AND c.relkind IN ('r','p')),
expected_columns AS (SELECT x.* FROM expected, jsonb_to_recordset(data->'columns') AS x(
 table_name text,column_name text,column_type text,not_null boolean,default_expr text)),
actual_columns AS (SELECT t.relname AS table_name,a.attname AS column_name,
 replace(format_type(a.atttypid,a.atttypmod),'extensions.','') AS column_type,a.attnotnull AS not_null,
 pg_get_expr(d.adbin,d.adrelid) AS default_expr
 FROM actual_tables t JOIN pg_attribute a ON a.attrelid=t.oid
 LEFT JOIN pg_attrdef d ON d.adrelid=t.oid AND d.adnum=a.attnum
 WHERE a.attnum>0 AND NOT a.attisdropped),
expected_constraints AS (SELECT x.* FROM expected,jsonb_to_recordset(data->'constraints') AS x(
 relname text,contype text,definition text)),
actual_constraints AS (SELECT t.relname,c.contype::text,pg_get_constraintdef(c.oid,true) AS definition,c.convalidated
 FROM pg_constraint c JOIN actual_tables t ON t.oid=c.conrelid
 WHERE c.contype <> 'n'), -- PG18 NOT NULL is verified by the column not_null manifest instead.
expected_indexes AS (SELECT x.* FROM expected,jsonb_to_recordset(data->'indexes') AS x(relname text,definition text)),
actual_indexes AS (SELECT t.relname,pg_get_indexdef(i.indexrelid) AS definition,i.indisvalid,i.indisunique
 FROM pg_index i JOIN actual_tables t ON t.oid=i.indrelid),
expected_policies AS (SELECT x.* FROM expected,jsonb_to_recordset(data->'policies') AS x(
 tablename text,policyname text,cmd text,qual text,with_check text,roles text[],permissive text)),
actual_policies AS (SELECT * FROM pg_policies WHERE schemaname='public'),
expected_privileges AS (SELECT x.* FROM expected,jsonb_to_recordset(data->'table_privileges') AS x(
 relname text,rolname text,can_select boolean,can_insert boolean,can_update boolean,can_delete boolean,
 can_truncate boolean,can_reference boolean,can_trigger boolean)),
expected_functions AS (SELECT x.* FROM expected,jsonb_to_recordset(data->'functions') AS x(
 name text,body_md5_lf text,security_definer boolean,anon boolean,authenticated boolean)),
actual_functions AS (SELECT p.* FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname='public' AND p.proname IN (SELECT name FROM expected_functions))
SELECT jsonb_build_object(
 'kind','STAGING_BASELINE_METADATA_NOT_API_ACCEPTANCE',
 'captured_at',CURRENT_TIMESTAMP,'executing_role',current_user,
 'server_version',current_setting('server_version'),
 'postgis',(SELECT jsonb_build_object('schema',n.nspname,'version',e.extversion)
  FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE e.extname='postgis'),
 'missing_tables',COALESCE((SELECT jsonb_agg(name) FROM expected_tables e
  WHERE NOT EXISTS(SELECT 1 FROM actual_tables t WHERE t.relname=e.name)),'[]'::jsonb),
 'unexpected_tables',COALESCE((SELECT jsonb_agg(relname) FROM actual_tables t
  WHERE NOT EXISTS(SELECT 1 FROM expected_tables e WHERE e.name=t.relname)),'[]'::jsonb),
 'table_security',COALESCE((SELECT jsonb_agg(jsonb_build_object('table',relname,'owner',pg_get_userbyid(relowner),
  'rls',relrowsecurity,'force',relforcerowsecurity)) FROM actual_tables),'[]'::jsonb),
 'column_mismatches',COALESCE((SELECT jsonb_agg(jsonb_build_object('expected',to_jsonb(e),'actual',to_jsonb(c)))
  FROM expected_columns e FULL JOIN actual_columns c USING(table_name,column_name)
  WHERE e.column_name IS NULL OR c.column_name IS NULL
   OR regexp_replace(lower(e.column_type),'\s','','g')<>regexp_replace(lower(c.column_type),'\s','','g')
   OR e.not_null IS DISTINCT FROM c.not_null
   OR regexp_replace(replace(replace(e.default_expr,'::text',''),'pg_catalog.',''),'\s','','g')
      IS DISTINCT FROM regexp_replace(replace(replace(c.default_expr,'::text',''),'pg_catalog.',''),'\s','','g')),'[]'::jsonb),
 'missing_or_different_constraints',COALESCE((SELECT jsonb_agg(to_jsonb(e)) FROM expected_constraints e WHERE NOT EXISTS(
  SELECT 1 FROM actual_constraints c WHERE c.relname=e.relname AND c.contype=e.contype AND c.convalidated
   AND regexp_replace(replace(c.definition,'public.',''),'\s','','g')=
       regexp_replace(replace(e.definition,'public.',''),'\s','','g'))),'[]'::jsonb),
 'unexpected_constraints',COALESCE((SELECT jsonb_agg(to_jsonb(c)) FROM actual_constraints c WHERE NOT EXISTS(
  SELECT 1 FROM expected_constraints e WHERE c.relname=e.relname AND c.contype=e.contype
   AND regexp_replace(replace(c.definition,'public.',''),'\s','','g')=
       regexp_replace(replace(e.definition,'public.',''),'\s','','g'))),'[]'::jsonb),
 'missing_or_invalid_indexes',COALESCE((SELECT jsonb_agg(to_jsonb(e)) FROM expected_indexes e WHERE NOT EXISTS(
  SELECT 1 FROM actual_indexes i WHERE i.relname=e.relname AND i.indisvalid
   AND regexp_replace(replace(i.definition,'public.',''),'\s','','g')=
       regexp_replace(replace(e.definition,'public.',''),'\s','','g'))),'[]'::jsonb),
 'policy_mismatches',COALESCE((SELECT jsonb_agg(jsonb_build_object('expected',to_jsonb(e),'actual',to_jsonb(p)))
  FROM expected_policies e FULL JOIN actual_policies p USING(tablename,policyname)
  WHERE e.policyname IS NULL OR p.policyname IS NULL OR e.cmd IS DISTINCT FROM p.cmd
   OR e.roles IS DISTINCT FROM p.roles::text[] OR e.permissive IS DISTINCT FROM p.permissive
   OR regexp_replace(replace(e.qual,'public.',''),'\s','','g') IS DISTINCT FROM regexp_replace(replace(p.qual,'public.',''),'\s','','g')
   OR regexp_replace(replace(e.with_check,'public.',''),'\s','','g') IS DISTINCT FROM regexp_replace(replace(p.with_check,'public.',''),'\s','','g')),'[]'::jsonb),
 'table_privilege_mismatches',COALESCE((SELECT jsonb_agg(to_jsonb(e)) FROM expected_privileges e
  LEFT JOIN actual_tables t ON t.relname=e.relname LEFT JOIN pg_roles r ON r.rolname=e.rolname
  WHERE t.oid IS NULL OR r.oid IS NULL OR
   has_table_privilege(r.oid,t.oid,'SELECT') IS DISTINCT FROM e.can_select OR
   has_table_privilege(r.oid,t.oid,'INSERT') IS DISTINCT FROM e.can_insert OR
   has_table_privilege(r.oid,t.oid,'UPDATE') IS DISTINCT FROM e.can_update OR
   has_table_privilege(r.oid,t.oid,'DELETE') IS DISTINCT FROM e.can_delete OR
   has_table_privilege(r.oid,t.oid,'TRUNCATE') IS DISTINCT FROM e.can_truncate OR
   has_table_privilege(r.oid,t.oid,'REFERENCES') IS DISTINCT FROM e.can_reference OR
   has_table_privilege(r.oid,t.oid,'TRIGGER') IS DISTINCT FROM e.can_trigger),'[]'::jsonb),
 'function_checks',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',e.name,
   'signature',pg_get_function_identity_arguments(p.oid),'return_type',pg_get_function_result(p.oid),
   'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'config',p.proconfig,
   'body_matches_baseline',md5(replace(p.prosrc,E'\r',''))=e.body_md5_lf,
   'definer_matches',p.prosecdef IS NOT DISTINCT FROM e.security_definer,
   'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),
   'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),
   'service_execute',has_function_privilege('service_role',p.oid,'EXECUTE'),
   'anon_matches',has_function_privilege('anon',p.oid,'EXECUTE') IS NOT DISTINCT FROM e.anon,
   'authenticated_matches',has_function_privilege('authenticated',p.oid,'EXECUTE') IS NOT DISTINCT FROM e.authenticated))
  FROM expected_functions e LEFT JOIN actual_functions p ON p.proname=e.name),'[]'::jsonb),
 'triggers',COALESCE((SELECT jsonb_agg(jsonb_build_object('table',t.relname,'name',g.tgname,'enabled',g.tgenabled,
   'definition',pg_get_triggerdef(g.oid,true))) FROM pg_trigger g JOIN actual_tables t ON t.oid=g.tgrelid
   WHERE NOT g.tgisinternal),'[]'::jsonb),
 'note','No function invocation or row data read. Also inspect extra functions/views, roles/default ACL/column grants via full audit. Seed/default baselines come from local Master; read-only seed checks are separate.'
) AS phase4a3_staging_structure;

-- Seeds and absence of bootstrap fixtures:
-- READ ONLY. Run only AFTER an approved persistent bootstrap on staging.
-- Selects only four static role codes/config counts, no user/operational rows.
WITH expected(code) AS (VALUES ('super_admin'),('information_manager'),
 ('report_verifier'),('mitigation_editor'))
SELECT e.code, count(r.id) AS matching_role_rows
FROM expected e LEFT JOIN public.roles r ON r.code=e.code GROUP BY e.code ORDER BY e.code;
SELECT count(*) AS role_rows, count(DISTINCT code) AS distinct_role_codes FROM public.roles;
SELECT count(*) AS source_config_rows FROM public.data_sources;
SELECT (SELECT count(*) FROM public.staff_profiles) AS staff_profiles_before_fixture,
       (SELECT count(*) FROM public.staff_role_assignments) AS assignments_before_fixture,
       (SELECT count(*) FROM public.public_reports) AS reports_before_fixture,
       (SELECT count(*) FROM public.report_status_history) AS history_before_fixture,
       (SELECT count(*) FROM public.report_access_tokens) AS tracking_tokens_before_fixture;
-- Expected immediately after bootstrap: 4/4 roles, 2 config sources, all five
-- fixture-related counts zero. Counts do not prove absence of private data in
-- unqueried tables; bootstrap source/target isolation must be independently reviewed.

